import { useEffect, useState } from 'react'
import { supabase } from '../lib/supabaseClient'
import { useAuth } from '../context/AuthContext'
import NotesOnboarding from '../pages/NotesOnboarding'

export default function RequireNotesProfile({ children }) {
  const { user } = useAuth() // session already exists — shared login
  const [status, setStatus] = useState('checking') // checking | missing | ok

  useEffect(() => {
    if (!user) return
    check()
  }, [user])

  async function check() {
    const { data, error } = await supabase
      .schema('notes')
      .from('profiles')
      .select('id')
      .eq('id', user.id)
      .maybeSingle()

    if (error) {
      console.error(error)
      setStatus('missing')
      return
    }
    setStatus(data ? 'ok' : 'missing')
  }

  if (status === 'checking') {
    return <div className="h-screen flex items-center justify-center">Loading…</div>
  }

  if (status === 'missing') {
    // Same auth session — just collects Notes-specific profile fields.
    return <NotesOnboarding onComplete={() => setStatus('ok')} />
  }

  return children
}