import React, { createContext, useContext, useEffect, useState } from "react";
import { supabase } from "../lib/supabaseClient";

const AuthContext = createContext(null);

export function AuthProvider({ children }) {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  // Check whether the authenticated user belongs to Notes
  const checkNotesAccess = async (userId) => {
  const { data, error } = await supabase
    .from("user_app_access")
    .select("app")
    .eq("user_id", userId)
    .eq("app", "notes")
    .maybeSingle();

  if (error) {
    console.error("Notes access check failed:", error);
    return false;
  }

  return !!data;
};

  useEffect(() => {
    let mounted = true;

    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange(async (event, session) => {
      if (!mounted) return;

      const currentUser = session?.user ?? null;

      if (!currentUser) {
        setUser(null);
        setLoading(false);
        return;
      }

      // Verify that this Auth user is registered for Notes
      const hasNotesAccess = await checkNotesAccess(currentUser.id);

      if (!mounted) return;

      if (!hasNotesAccess) {
        console.log("User is not registered for Notes.");

        await supabase.auth.signOut();

        if (mounted) {
          setUser(null);
          setLoading(false);
        }

        return;
      }

      setUser(currentUser);
      setLoading(false);
    });

    supabase.auth
      .getSession()
      .then(async ({ data: { session } }) => {
        if (!mounted) return;

        const currentUser = session?.user ?? null;

        if (!currentUser) {
          setUser(null);
          setLoading(false);
          return;
        }

        // Verify Notes access when restoring an existing session
        const hasNotesAccess = await checkNotesAccess(currentUser.id);

        if (!mounted) return;

        if (!hasNotesAccess) {
          console.log("Existing session has no Notes access.");

          await supabase.auth.signOut();

          if (mounted) {
            setUser(null);
            setLoading(false);
          }

          return;
        }

        setUser(currentUser);
        setLoading(false);
      })
      .catch((error) => {
        console.error("Error restoring session:", error);

        if (mounted) {
          setUser(null);
          setLoading(false);
        }
      });

    return () => {
      mounted = false;
      subscription.unsubscribe();
    };
  }, []);

  // NOTES SIGNUP
  const signUp = async (email, password, fullName) => {
    const result = await supabase.auth.signUp({
      email,
      password,
      options: {
        data: {
          full_name: fullName,
          app: "notes",
        },
      },
    });

    // Notes access is granted server-side by the
    // on_auth_user_created_app_access trigger (reads user_metadata.app),
    // so no client-side insert is needed here — it also avoids the
    // "permission denied" error that happens when email confirmation
    // is ON and there's no session yet right after signUp.
    return result;
  };

  // NOTES LOGIN
  const signIn = async (email, password) => {
    const result = await supabase.auth.signInWithPassword({
      email,
      password,
    });

    if (result.error) {
      return result;
    }

    const loggedInUser = result.data?.user;

    if (!loggedInUser) {
      return {
        ...result,
        error: new Error("User authentication failed."),
      };
    }

    // Check Notes access
    const hasNotesAccess = await checkNotesAccess(loggedInUser.id);

    if (!hasNotesAccess) {
      await supabase.auth.signOut();

      return {
        ...result,
        data: {
          ...result.data,
          session: null,
        },
        error: new Error(
          "This account is not registered for Notes. Please register in Notes first."
        ),
      };
    }

    // Only record login after Notes access is confirmed
    const fullName =
      loggedInUser.user_metadata?.full_name ?? null;

    supabase
      .rpc("record_login", {
        p_username: fullName,
        p_email: email,
      })
      .then(({ error }) => {
        if (error) {
          console.error("record_login failed:", error);
        }
      });

    return result;
  };

  const signOut = async () => {
    try {
      await supabase.rpc("record_logout");
    } catch (error) {
      console.error("record_logout failed:", error);
    }

    return supabase.auth.signOut();
  };

  const resetPassword = (email) =>
    supabase.auth.resetPasswordForEmail(email, {
      redirectTo:
        window.location.origin + "/Notes/reset-password",
    });

  const value = {
    user,
    loading,
    signUp,
    signIn,
    signOut,
    resetPassword,
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
}

export const useAuth = () => useContext(AuthContext);