import { createClient } from "@supabase/supabase-js";

const supabaseUrl = process.env.REACT_APP_SUPABASE_URL;
const supabaseAnonKey = process.env.REACT_APP_SUPABASE_ANON_KEY;

if (!supabaseUrl || !supabaseAnonKey) {
  // Fails loudly in dev instead of silently breaking every fetch
  // eslint-disable-next-line no-console
  console.error(
    "Missing Supabase env vars. Copy .env.example to .env and fill in " +
      "REACT_APP_SUPABASE_URL and REACT_APP_SUPABASE_ANON_KEY."
  );
}

// All app tables live in the "notes" Postgres schema (not the default
// "public" one) - see supabase/01_schema.sql. Make sure "notes" is added
// under Project Settings -> Data API -> Exposed schemas in your Supabase
// dashboard, or every request below will fail with a 404/406.
//
// auth.storage is set to sessionStorage (instead of the default
// localStorage) so the login session only lives for the current browser
// tab/window - closing the browser clears it and the user has to log in
// again next time, instead of staying signed in indefinitely.
export const supabase = createClient(supabaseUrl, supabaseAnonKey, {
  db: { schema: "notes" },
  auth: {
    storage: window.sessionStorage,
    persistSession: true,
    autoRefreshToken: true,
  },
});